window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-34b2fcd159218423"]={"versions": [{"id": "FIG-34b2fcd159218423", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von textuellen Strings im AUTOSAR-Metamodell (Template <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm modelliert die strukturelle Anbindung von String-Eigenschaften (<code>SwTextProps</code>) über softwarebezogene Datendefinitionseigenschaften (<code>SwDataDefProps</code>) an anwendungsspezifische primitive Datentypen (<code>ApplicationPrimitiveDataType</code>) sowie an hardwarenahe Basistypen (<code>SwBaseType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen, Vererbungsbeziehungen und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong>AutosarDataType</strong> (Stereotypen <code>ARElement</code>, <code>AtpType</code>, abstrakt): Basisklasse für Datentypen im Metamodell. Besitzt eine gerichtete Komposition <code>+swDataDefProps</code> (Kardinalität <code>0..1</code>) zur Klasse <code>SwDataDefProps</code>.</li>\n<li><strong>ApplicationDataType</strong> (Stereotypen <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, abstrakt): Spezialisiert <code>AutosarDataType</code>.</li>\n<li><strong>ApplicationPrimitiveDataType</strong>: Spezialisiert <code>ApplicationDataType</code>. Repräsentiert primitive Anwendungsdatentypen, hier insbesondere textuelle Zeichenketten.</li>\n<li><strong>SwDataDefProps</strong> (Stereotyp <code>«atpVariation»</code>): Bündelt softwarespezifische Datendefinitionseigenschaften. Enthält Attribute:</li>\n<li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code></li>\n<li><code>displayFormat: DisplayFormatString [0..1]</code></li>\n<li><code>mcFunction: Identifier [0..1]</code></li>\n<li><code>swAlignment: AlignmentType [0..1]</code></li>\n<li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code></li>\n<li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code></li>\n<li><code>swIntendedResolution: Numerical [0..1]</code></li>\n<li><code>swInterpolationMethod: Identifier [0..1]</code></li>\n<li><code>swIsVirtual: Boolean [0..1]</code></li>\n<li><code>swValueBlockSize: Numerical [0..1]</code> (mit Stereotyp <code>«atpVariation»</code>)</li>\n<li>Komposition <code>+swTextProps</code> (Kardinalität <code>0..1</code>) zur Klasse <code>SwTextProps</code>.</li>\n<li><strong>SwTextProps</strong>: Beschreibt spezifische Eigenschaften von textuellen Zeichenketten mit folgenden Attributen:</li>\n<li><code>arraySizeSemantics: ArraySizeSemanticsEnum</code></li>\n<li><code>swFillCharacter: Integer [0..1]</code></li>\n<li><code>swMaxTextSize: Integer</code> (mit Stereotyp <code>«atpVariation»</code>)</li>\n<li>Gerichtete Assoziation <code>+baseType</code> (Kardinalität <code>0..1</code>) auf <code>SwBaseType</code>.</li>\n<li><strong>SwBaseType</strong> (Stereotypen <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>BaseType</code>): Beschreibt den zugrundeliegenden Plattform- bzw. Maschinendatentyp für die Speicherung der Zeichenkette.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm enthält das Diagramm keine dynamischen Verhaltensbeschreibungen, Sequenzabläufe, Zustandsübergänge oder Interaktionspfade.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Textuelle Strings werden auf Anwendungsebene als <code>ApplicationPrimitiveDataType</code> modelliert, deren textuelle Semantik über die Kompositionskette <code>AutosarDataType</code> -> <code>SwDataDefProps</code> -> <code>SwTextProps</code> festgelegt wird. <code>swMaxTextSize</code> definiert dabei die maximale Zeichenanzahl unter Berücksichtigung von Variationspunkten (<code>«atpVariation»</code>). Die Semantik variabler oder fixer Längen wird über <code>arraySizeSemantics</code> und Füllzeichen über <code>swFillCharacter</code> vorgegeben. Für die Plattform-Realisierung verweist <code>SwTextProps</code> über <code>baseType</code> auf den konkreten <code>SwBaseType</code> (z. B. Kodierung bzw. native Zeichengröße).</p>"}, {"id": "FIG-4fa74436a102dc43", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von textuellen Strings im AUTOSAR-Metamodell (Template <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm modelliert die strukturelle Anbindung von String-Eigenschaften (<code>SwTextProps</code>) über softwarebezogene Datendefinitionseigenschaften (<code>SwDataDefProps</code>) an anwendungsspezifische primitive Datentypen (<code>ApplicationPrimitiveDataType</code>) sowie an hardwarenahe Basistypen (<code>SwBaseType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen, Vererbungsbeziehungen und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong>AutosarDataType</strong> (Stereotypen <code>ARElement</code>, <code>AtpType</code>, abstrakt): Basisklasse für Datentypen im Metamodell. Besitzt eine gerichtete Komposition <code>+swDataDefProps</code> (Kardinalität <code>0..1</code>) zur Klasse <code>SwDataDefProps</code>.</li>\n<li><strong>ApplicationDataType</strong> (Stereotypen <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, abstrakt): Spezialisiert <code>AutosarDataType</code>.</li>\n<li><strong>ApplicationPrimitiveDataType</strong>: Spezialisiert <code>ApplicationDataType</code>.</li>\n<li><strong>SwDataDefProps</strong> (Stereotyp <code>«atpVariation»</code>): Bündelt Datendefinitionseigenschaften. Enthält Attribute:</li>\n<li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code></li>\n<li><code>displayFormat: DisplayFormatString [0..1]</code></li>\n<li><code>mcFunction: Identifier [0..1]</code></li>\n<li><code>swAlignment: AlignmentType [0..1]</code></li>\n<li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code></li>\n<li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code></li>\n<li><code>swIntendedResolution: Numerical [0..1]</code></li>\n<li><code>swInterpolationMethod: Identifier [0..1]</code></li>\n<li><code>swIsVirtual: Boolean [0..1]</code></li>\n<li><code>swValueBlockSize: Numerical [0..1]</code> (mit Stereotyp <code>«atpVariation»</code>)</li>\n<li>Gerichtete Assoziation <code>+swRecordLayout</code> (Kardinalität <code>0..1</code>) auf <code>SwRecordLayout</code>.</li>\n<li>Gerichtete Komposition <code>+invalidValue</code> (Kardinalität <code>0..1</code>) auf <code>ValueSpecification</code>.</li>\n<li>Gerichtete Komposition <code>+swTextProps</code> (Kardinalität <code>0..1</code>) auf <code>SwTextProps</code>.</li>\n<li><strong>SwRecordLayout</strong> (Stereotyp <code>ARElement</code>): Spezifiziert das Speicherlayout für Mess- und Kalibriergrößen.</li>\n<li><strong>ValueSpecification</strong> (abstrakt): Basisklasse für Wertszenarien und -spezifikationen mit dem Attribut:</li>\n<li><code>shortLabel: Identifier [0..1]</code></li>\n<li><strong>ApplicationValueSpecification</strong>: Spezialisiert <code>ValueSpecification</code> mit dem Attribut:</li>\n<li><code>category: Identifier</code></li>\n<li><strong>SwTextProps</strong>: Spezifiziert textuelle String-Eigenschaften mit den Attributen:</li>\n<li><code>arraySizeSemantics: ArraySizeSemanticsEnum</code></li>\n<li><code>swFillCharacter: Integer [0..1]</code></li>\n<li><code>swMaxTextSize: Integer</code> (mit Stereotyp <code>«atpVariation»</code>)</li>\n<li>Gerichtete Assoziation <code>+baseType</code> (Kardinalität <code>0..1</code>) auf <code>SwBaseType</code>.</li>\n<li><strong>SwBaseType</strong> (Stereotypen <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>BaseType</code>): Repräsentiert den elementaren Basis-Datentyp.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm enthält das Diagramm keine dynamischen Verhaltensbeschreibungen, Sequenzabläufe, Zustandsübergänge oder Interaktionspfade.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Textuelle Zeichenketten werden über <code>ApplicationPrimitiveDataType</code> und <code>SwDataDefProps</code> definiert, wobei <code>SwTextProps</code> spezifische Parameter wie maximale Textlänge (<code>swMaxTextSize</code>), Längensemantik (<code>arraySizeSemantics</code>), Füllzeichen (<code>swFillCharacter</code>) und die Typbindung an <code>SwBaseType</code> festlegt. Über die Komposition <code>invalidValue</code> kann direkt an <code>SwDataDefProps</code> ein ungültiger Ersatzwert (<code>ValueSpecification</code> bzw. <code>ApplicationValueSpecification</code>) zugeordnet werden. Die Assoziation <code>swRecordLayout</code> ermöglicht zudem die formale Festlegung eines spezifischen Speicherlayouts für Mess- und Kalibrierwerkzeuge.</p>"}], "trans": [{"from": "FIG-34b2fcd159218423", "to": "FIG-4fa74436a102dc43", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziation <code>swRecordLayout</code> (Kardinalität <code>0..1</code>) von <code>SwDataDefProps</code> auf das Element <code>SwRecordLayout</code> (Stereotypen <code>ARElement</code>) neu aufgenommen.</li>\n<li>Komposition <code>invalidValue</code> (Rolle <code>+invalidValue</code>, Kardinalität <code>0..1</code>) von <code>SwDataDefProps</code> auf die abstrakte Klasse <code>ValueSpecification</code> (mit Attribut <code>shortLabel: Identifier [0..1]</code>) und deren Spezialisierung <code>ApplicationValueSpecification</code> (mit Attribut <code>category: Identifier</code>) neu hinzugefügt.</li>\n</ul>"}]};
